from collections import deque

def transform(grid):
    h, w = len(grid), len(grid[0])
    seen = set()
    comps = []

    for r in range(h):
        for c in range(w):
            if grid[r][c] != 0 or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            comp = []
            while q:
                x, y = q.popleft()
                comp.append((x, y))
                for dx, dy in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    nx, ny = x + dx, y + dy
                    if 0 <= nx < h and 0 <= ny < w and grid[nx][ny] == 0 and (nx, ny) not in seen:
                        seen.add((nx, ny))
                        q.append((nx, ny))
            comps.append(comp)

    out = [row[:] for row in grid]
    if len(comps) >= 2:
        largest = max(range(len(comps)), key=lambda i: len(comps[i]))
        smallest = min((i for i in range(len(comps)) if i != largest),
                       key=lambda i: len(comps[i]))
        for r, c in comps[largest]:
            out[r][c] = 8
        for r, c in comps[smallest]:
            out[r][c] = 7
    return out
